	@Test
	void lateCompletedCacheValueCannotBorrowAnActualRebindsProvenance() throws Exception {
		ValueStore store = new ValueStore(directory.resolve("cache-values").toFile(), new LmdbStoreConfig());
		CountDownLatch capturedId = new CountDownLatch(1);
		CountDownLatch releaseId = new CountDownLatch(1);
		AtomicBoolean armed = new AtomicBoolean(true);
		Thread[] reader = new Thread[1];
		try {
			store.startTransaction(true);
			long oldId = store.storeValue(VF.createBNode("cache-original"));
			store.commit();
			ReadySource source = initializedSource(store, oldId);
			ValueStoreRevision originalRevision = source.value.getValueStoreRevision();
			LmdbBNode ready = new LmdbBNode(originalRevision, "cache-original", oldId) {
				@Override
				public long getInternalID() {
					long captured = super.getInternalID();
					if (Thread.currentThread() == reader[0] && armed.compareAndSet(true, false)) {
						capturedId.countDown();
						await(releaseId);
					}
					return captured;
				}
			};
			retire(store, oldId);
			awaitCollection(source.collected);
			store.forceEvictionOfValues();
			store.startTransaction(true);
			assertEquals(oldId, store.storeValue(VF.createBNode("cache-replacement")),
					"The late completion must address an actually reassigned native compound ID");
			store.commit();
			// A completion belongs to its resolving source revision even if the ready target is later rebound.
			originalRevision.valueInitialized(oldId, ready);
			FutureTask<LmdbValue> lookup = new FutureTask<>(() -> store.getValue(oldId));
			reader[0] = new Thread(lookup, "lmdb-value-cache-identity-reader");
			reader[0].start();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(TIMEOUT_SECONDS);
			while (capturedId.getCount() != 0 && !lookup.isDone() && System.nanoTime() < deadline) {
				Thread.yield();
			}
			assertTrue(capturedId.getCount() == 0 || lookup.isDone(),
					"Lookup must either inspect the candidate or reject its original cache provenance");
			store.startTransaction(true);
			long reboundId;
			try {
				reboundId = store.storeValue(ready);
				assertNotEquals(oldId, reboundId,
						"The real writer must publish a distinct identity for the old payload");
				store.commit();
			} finally {
				store.rollback();
			}
			releaseId.countDown();
			assertEquals("cache-replacement", lookup.get(TIMEOUT_SECONDS, TimeUnit.SECONDS).stringValue(),
					"A late old cache completion must not acquire provenance from a later model rebind");
			assertEquals("cache-original", store.getValue(reboundId).stringValue());
			assertEquals("cache-replacement", store.getValue(oldId).stringValue());
			assertEquals(reboundId, store.getId(ready));
		} finally {
			releaseId.countDown();
			if (reader[0] != null) {
				reader[0].join(TimeUnit.SECONDS.toMillis(TIMEOUT_SECONDS));
				assertFalse(reader[0].isAlive(), "The cache worker must drain before native store close");
			}
			store.rollback();
			store.close();
		}
	}

	private void assertEqualitySurvivesActualRebind(Shape shape, boolean unknown) throws Exception {
		ValueStore store = new ValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig().setInlineLiterals(false).setValueHashCacheEnabled(true));
		CountDownLatch comparedRevision = new CountDownLatch(1);
		CountDownLatch releaseComparison = new CountDownLatch(1);
		Thread comparison = null;
		try {
			Value original = shape.payload("original");
			store.startTransaction(true);
			long oldId = store.storeValue(original);
			store.commit();
			ReadySource source = initializedSource(store, oldId);
			PausingRevision revision = new PausingRevision(source.value.getValueStoreRevision(), comparedRevision,
					releaseComparison);
			LmdbValue value = shape.ready(revision, original, unknown ? LmdbValue.UNKNOWN_ID : oldId);
			LmdbValue peer = shape.ready(revision, original, oldId);
			FutureTask<Boolean> equality = new FutureTask<>(() -> value.equals(peer));
			comparison = new Thread(equality, "lmdb-value-identity-comparison");
			revision.comparison = comparison;
			comparison.start();
			await(comparedRevision);
			retire(store, oldId);
			awaitCollection(source.collected);
			store.forceEvictionOfValues();
			store.startTransaction(true);
			try {
				long replacementId = store.storeValue(shape.payload("replacement"));
				assertEquals(oldId, replacementId, "The native dictionary must actually reassign the retired ID");
				long reboundId = store.storeValue(value);
				assertNotEquals(oldId, reboundId, "The ready value must be rebound through the public writer API");
				store.commit();
				releaseComparison.countDown();
				assertTrue(equality.get(TIMEOUT_SECONDS, TimeUnit.SECONDS),
						"Identical payloads must remain equal across a concurrent real dictionary rebind");
				assertEquals(reboundId, store.getId(value),
						"Equality must not overwrite the identity published by the real writer");
				assertEquals(original, store.getValue(reboundId));
				assertEquals(shape.payload("replacement"), store.getValue(oldId));
				assertEquals(original.hashCode(), value.hashCode(), "Hashing must retain the value's own payload");
				assertTrue(value.equals(original));
			} finally {
				store.rollback();
			}
		} finally {
			releaseComparison.countDown();
			if (comparison != null) {
				comparison.join(TimeUnit.SECONDS.toMillis(TIMEOUT_SECONDS));
				assertFalse(comparison.isAlive(), "The comparison worker must drain before native store close");
			}
			store.close();
		}
	}

	/** The capture switch is used once before the model's serialized field layout changes. */
	@Test
	void serializedModelsRetainExistingPayloadAndIdentity() throws Exception {
		String capturePath = System.getProperty("rdf4j.lmdb.identity.captureFixture");
		if (capturePath != null) {
			Path fixture = Path.of(capturePath);
			assertFalse(Files.exists(fixture), "A pre-change fixture must never be overwritten");
			Files.createDirectories(fixture.getParent());
			ValueStore store = new ValueStore(directory.resolve("serialized-values").toFile(),
					new LmdbStoreConfig().setInlineLiterals(false));
			try {
				Shape[] shapes = Shape.values();
				LmdbValue[] values = new LmdbValue[shapes.length * 2];
				long[] ids = new long[values.length];
				String[] payloads = new String[values.length];
				for (int i = 0; i < shapes.length; i++) {
					Value payload = shapes[i].payload("serialized");
					store.startTransaction(true);
					long id = store.storeValue(payload);
					store.commit();
					values[i] = store.getValue(id);
					readFully(values[i]);
					values[i + shapes.length] = shapes[i].ready(store.getRevision(), payload, LmdbValue.UNKNOWN_ID);
				}
				for (int i = 0; i < values.length; i++) {
					ids[i] = values[i].getInternalID();
					payloads[i] = values[i].toString();
				}
				try (ObjectOutputStream output = new ObjectOutputStream(Files.newOutputStream(fixture))) {
					output.writeObject(values);
					output.writeObject(ids);
					output.writeObject(payloads);
				}
			} finally {
				store.close();
			}
			try (InputStream input = Files.newInputStream(fixture)) {
				assertSerializedFixture(input);
			}
		} else {
			try (InputStream input = getClass().getResourceAsStream(SERIALIZED_FIXTURE)) {
				assertNotNull(input, "The pre-layout fixture must be staged before changing model identity fields");
				assertSerializedFixture(input);
			}
		}
	}

	private static void assertSerializedFixture(InputStream input) throws Exception {
		try (ObjectInputStream objects = new ObjectInputStream(input)) {
			LmdbValue[] values = (LmdbValue[]) objects.readObject();
			long[] ids = (long[]) objects.readObject();
			String[] payloads = (String[]) objects.readObject();
			assertEquals(Shape.values().length * 2, values.length);
			for (int i = 0; i < values.length; i++) {
				assertSame(values[i].getInternalIdentity(), values[i].getInternalIdentity(),
						"Built-in identity reads must return the immutable publication without allocation");
				assertEquals(ids[i], values[i].getInternalID());
				assertNotNull(values[i].getValueStoreRevision());
				assertEquals(payloads[i], values[i].toString());
				readFully(values[i]);
				assertTrue(values[i].equals(values[i]));
				assertEquals(values[i].hashCode(), values[i].hashCode());
			}
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
				output.writeObject(values);
			}
			try (ObjectInputStream roundTrip = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
				LmdbValue[] writtenValues = (LmdbValue[]) roundTrip.readObject();
				for (int i = 0; i < writtenValues.length; i++) {
					assertEquals(ids[i], writtenValues[i].getInternalID());
					assertEquals(values[i].getValueStoreRevision(), writtenValues[i].getValueStoreRevision());
					assertEquals(payloads[i], writtenValues[i].toString());
					readFully(writtenValues[i]);
				}
			}
		}
	}

	private ReadySource initializedSource(ValueStore store, long id) throws Exception {
		LmdbValue value = store.getLazyValue(id);
		CountDownLatch collected = new CountDownLatch(1);
		cleaner.register(value.getValueStoreRevision(), collected::countDown);
		readFully(value);
		return new ReadySource(value, collected);
	}

	private static void readFully(Value value) {
		value.stringValue();
		if (value instanceof TripleTerm term) {
			readFully(term.getSubject());
			readFully(term.getPredicate());
			readFully(term.getObject());
		} else if (value instanceof Literal literal) {
			literal.getLabel();
			literal.getLanguage();
			literal.getBaseDirection();
			literal.getCoreDatatype();
			readFully(literal.getDatatype());
		}
	}

	private static void retire(ValueStore store, long id) throws Exception {
		store.startTransaction(true);
		Set<Long> pending = Set.of(id);
		while (!pending.isEmpty()) {
			Set<Long> next = new HashSet<>();
			store.gcIds(pending, next);
			pending = next;
		}
		store.commit();
	}

	private void awaitCollection(CountDownLatch collected) throws Exception {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(TIMEOUT_SECONDS);
		while (collected.getCount() != 0 && System.nanoTime() < deadline) {
			System.gc();
			collected.await(100, TimeUnit.MILLISECONDS);
		}
		assertEquals(0, collected.getCount(), "The initialized model must release its retired Lazy cohort");
		CountDownLatch cleanup = new CountDownLatch(1);
		cleaner.register(new Object(), cleanup::countDown);
		deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(TIMEOUT_SECONDS);
		while (cleanup.getCount() != 0 && System.nanoTime() < deadline) {
			System.gc();
			cleanup.await(100, TimeUnit.MILLISECONDS);
		}
		assertEquals(0, cleanup.getCount(), "The cleaner must finish the dictionary cohort retirement");
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(TIMEOUT_SECONDS, TimeUnit.SECONDS), "The owned fixture latch must complete");
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

	private record ReadySource(LmdbValue value, CountDownLatch collected) {
	}

	private static final class PausingRevision extends ValueStoreRevision.Base {
		private final ValueStoreRevision delegate;
		private final CountDownLatch compared;
		private final CountDownLatch release;
		private final AtomicBoolean armed = new AtomicBoolean(true);
		private Thread comparison;

		PausingRevision(ValueStoreRevision delegate, CountDownLatch compared, CountDownLatch release) {
			this.delegate = delegate;
			this.compared = compared;
			this.release = release;
		}

		@Override
		public boolean equals(Object other) {
			boolean same = delegate.equals(other);
			if (Thread.currentThread() == comparison && armed.compareAndSet(true, false)) {
				compared.countDown();
				await(release);
			}
			return same;
		}

		@Override
		public long getRevisionId() {
			return delegate.getRevisionId();
		}

		@Override
		public ValueStore getValueStore() {
			return delegate.getValueStore();
		}

		@Override
		public boolean resolveValue(long id, LmdbValue value) {
			return delegate.resolveValue(id, value);
		}
	}

	private enum Shape {
		IRI,
		LITERAL,
		BNODE,
		TRIPLE_TERM,
		NESTED_TERM;

		Value payload(String suffix) {
			return switch (this) {
			case IRI -> VF.createIRI("urn:identity:" + suffix);
			case LITERAL -> VF.createLiteral("identity-" + suffix, "en", Literal.BaseDirection.RTL);
			case BNODE -> VF.createBNode("identity-" + suffix);
			case TRIPLE_TERM -> VF.createTripleTerm(VF.createBNode("subject-" + suffix),
					VF.createIRI("urn:predicate:" + suffix), VF.createLiteral("object-" + suffix));
			case NESTED_TERM -> VF.createTripleTerm(VF.createBNode("outer-subject-" + suffix),
					VF.createIRI("urn:outer-predicate:" + suffix),
					VF.createTripleTerm(VF.createBNode("inner-subject-" + suffix),
							VF.createIRI("urn:inner-predicate:" + suffix), VF.createLiteral("inner-object-" + suffix)));
			};
		}

		LmdbValue ready(ValueStoreRevision revision, Value payload, long id) {
			return switch (this) {
			case IRI -> new LmdbIRI(revision, payload.stringValue(), id);
			case LITERAL -> {
				Literal literal = (Literal) payload;
				yield new LmdbLiteral(revision, literal.getLabel(), literal.getLanguage().orElseThrow(),
						literal.getBaseDirection(), id);
			}
			case BNODE -> new LmdbBNode(revision, payload.stringValue(), id);
			case TRIPLE_TERM, NESTED_TERM -> {
				TripleTerm term = (TripleTerm) payload;
				yield new LmdbTripleTerm(revision, term.getSubject(), term.getPredicate(), term.getObject(), id);
			}
			};
		}
	}
